import React, { useState, useEffect, useRef, useCallback } from 'react';
import axios from 'axios';
import './App.css';

// Server URL - This will be proxied through the React proxy configuration
const SERVER_URL = '/api';

// Placeholder Google logo image (base64 encoded small Google logo)
const PLACEHOLDER_IMAGE = 'data:image/png;base64,';

function App() {
    const [sessionId, setSessionId] = useState(null);
    const [inputValue, setInputValue] = useState('');
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [browserImage, setBrowserImage] = useState(PLACEHOLDER_IMAGE); // Set initial placeholder image
    const [previewVisible, setPreviewVisible] = useState(true);
    // Add state for status messages
    const [statusMessages, setStatusMessages] = useState([{
        type: 'info',
        text: 'Test starting...',
        time: new Date().toLocaleTimeString()
    }]);
    // Add state for streaming
    const [streaming, setStreaming] = useState(false);
    const [streamStatus, setStreamStatus] = useState('waiting');
    const eventSourceRef = useRef(null);
    const messagesEndRef = useRef(null);
    // Add state for showing technical messages
    const [showTechnicalMessages, setShowTechnicalMessages] = useState(true);
    // Add polling interval references
    const messagePollingRef = useRef(null);
    const statusPollingRef = useRef(null);

    // Toggle display of technical messages
    const toggleTechnicalMessages = () => {
        setShowTechnicalMessages(!showTechnicalMessages);
    };

    // Helper function to add status messages with a timestamp
    const addStatusMessage = (type, text) => {
        const now = new Date();
        const timeString = now.toLocaleTimeString();
        setStatusMessages(prev => {
            // Keep only the most recent 10 messages
            const newMessages = [...prev, { type, text, time: timeString }];
            if (newMessages.length > 10) {
                return newMessages.slice(newMessages.length - 10);
            }
            return newMessages;
        });
    };

    // Helper to determine status type classes
    const getStatusType = (event) => {
        switch (event) {
            case 'error': return 'error';
            case 'thinking': return 'processing';
            case 'user-message': return 'user';
            case 'ai-response': return 'assistant';
            case 'tool-call': return 'tool';
            case 'response-complete': return 'success';
            case 'warning': return 'warning';
            case 'reconnecting': return 'reconnecting';
            default: return 'info';
        }
    };

    // Helper function to fetch messages directly from the API - memoized with useCallback
    const fetchMessagesDirectly = useCallback(() => {
        if (!sessionId) return;

        console.log('Fetching messages directly via API...');

        axios.get(`/api/messages/${sessionId}?_t=${Date.now()}`)
            .then(response => {
                if (response.data.success && response.data.messages) {
                    // Get current and new messages for comparison
                    const currentMessages = messages;
                    const newMessages = response.data.messages;

                    // Check if we have any new messages at all
                    if (newMessages.length <= currentMessages.length &&
                        !isAssistantMessageUpdated(currentMessages, newMessages)) {
                        console.log('No new messages or updates');
                        return;
                    }

                    // Log what we received
                    console.log(`API returned ${newMessages.length} messages (we have ${currentMessages.length})`);

                    // Find the assistant message that's being updated (if any)
                    const lastUserMessageIndex = findLastIndex(newMessages, m => m.role === 'user');
                    const assistantMessages = newMessages.filter((m, i) =>
                        i > lastUserMessageIndex && m.role === 'assistant'
                    );

                    // Improved completion check using multiple signals
                    const hasCompleteResponse = isResponseComplete(newMessages, assistantMessages);

                    // Update messages in state
                    setMessages(newMessages);

                    // Only set loading to false if we have a complete response or tools have been called
                    const toolMessages = newMessages.filter(m => m.role === 'tool' || m.role === 'function');

                    if (hasCompleteResponse) {
                        setLoading(false);
                        addStatusMessage('success', 'Response complete');
                    } else if (toolMessages.length > 0) {
                        // If we have tool calls but no complete response yet, show an appropriate message
                        addStatusMessage('processing', `Processing tool calls (${toolMessages.length} tools used so far)`);
                    }

                    // Add status message about progress
                    if (newMessages.length > currentMessages.length) {
                        const newCount = newMessages.length - currentMessages.length;
                        addStatusMessage('info', `Received ${newCount} new message${newCount > 1 ? 's' : ''}`);
                    } else if (isAssistantMessageUpdated(currentMessages, newMessages)) {
                        addStatusMessage('info', 'Assistant response updated');
                    }
                } else {
